"""Quinze analyses SQL : résultats calculés, pas de tableaux saisis à la main."""
import json,sqlite3,time
from pathlib import Path
from shapely.geometry import shape,Point
from pyproj import Geod
from national.collect import ROOT,dump
ANALYSES=[
('01','Quelle couverture climatique par département ?',"SELECT d.code,d.name,COUNT(c.code) communes,COUNT(cp.commune_code) climat,ROUND(100.0*COUNT(cp.commune_code)/COUNT(c.code),2) pct FROM commune c LEFT JOIN department d ON d.code=c.department LEFT JOIN climate_place cp ON cp.commune_code=c.code GROUP BY d.code ORDER BY d.code",'Une fiche disponible ne signifie pas un diagnostic à l’adresse.'),
('02','Quels inventaires communaux sont présents ?',"SELECT h.label,COUNT(*) communes FROM commune_hazard ch JOIN hazard h USING(hazard_id) GROUP BY h.hazard_id ORDER BY communes DESC",'Il s’agit de signalements communaux, pas du nombre de logements exposés.'),
('03','Combien de données par horizon et ensemble ?',"SELECT period_id,model_id,COUNT(*) valeurs,COUNT(DISTINCT commune_code) communes FROM climate_value GROUP BY period_id,model_id ORDER BY model_id,period_id",'Les domaines et références restent séparés. Les combinaisons absentes sont non couvertes.'),
('04','Que change le niveau TRACC pour les jours très chauds ?',"SELECT c.name,v.period_id,v.value,v.lower,v.upper,i.unit,cp.reference_start,cp.reference_end FROM climate_value v JOIN commune c ON c.code=v.commune_code JOIN climate_place cp USING(commune_code) JOIN indicator i USING(indicator_id) WHERE v.indicator_id='S1' AND v.season='annuel' AND c.code IN('17300','13004','31555','2A004','97411') ORDER BY c.name,v.period_id",'Médianes et bornes du producteur ; les différences ne sont pas des prévisions météorologiques.'),
('05','Écart de température à référence compatible ?',"SELECT c.name,p.value-r.value delta_c,p.value projection,r.value reference FROM climate_value p JOIN climate_value r ON r.commune_code=p.commune_code AND r.indicator_id=p.indicator_id AND r.season=p.season AND r.period_id='ref' JOIN commune c ON c.code=p.commune_code JOIN climate_place cp ON cp.commune_code=c.code WHERE p.period_id='2050' AND p.indicator_id='G1' AND p.season='été' AND cp.domain='France hexagonale' ORDER BY delta_c DESC LIMIT 20",'Soustraction au sein du même produit et de la même référence, sans ERA5. Pas un classement résidentiel.'),
('06','Couverture des galeries par catégorie ?',"WITH categories(category) AS (VALUES('fossil'),('organism'),('place')) SELECT ca.category,COUNT(DISTINCT o.occurrence_id) covered,(SELECT COUNT(*) FROM fossil_occurrence) total,ROUND(100.0*COUNT(DISTINCT o.occurrence_id)/(SELECT COUNT(*) FROM fossil_occurrence),3) pct FROM categories ca LEFT JOIN media m ON m.category=ca.category LEFT JOIN taxon_media tm USING(media_id) LEFT JOIN fossil_occurrence o USING(taxon_id) GROUP BY ca.category",'Couverture d’une illustration associée au taxon ; ne prouve pas une photographie du spécimen local. Le fond aérien n’est pas une photo référencée par site.'),
('07','Quels niveaux de correspondance des images ?',"SELECT tm.match_level,m.category,COUNT(DISTINCT tm.taxon_id) taxa,COUNT(DISTINCT m.media_id) images FROM taxon_media tm JOIN media m USING(media_id) GROUP BY tm.match_level,m.category",'Une illustration du même genre peut correspondre à une autre espèce.'),
('08','Quelles périodes et classes sont documentées ?',"SELECT i.early_name,t.class_name,COUNT(*) occurrences,COUNT(DISTINCT o.site_id) sites FROM fossil_occurrence o JOIN taxon t USING(taxon_id) JOIN geological_interval i USING(interval_id) GROUP BY i.early_name,t.class_name ORDER BY occurrences DESC LIMIT 30",'Les occurrences ne comptent pas des animaux ; biais de collecte et de publication.'),
('09','La bibliographie est-elle concentrée ?',"WITH n AS (SELECT reference_id,COUNT(*) n FROM fossil_occurrence GROUP BY reference_id) SELECT b.reference_id,n.n,ROUND(100.0*n.n/SUM(n.n) OVER(),2) pct,DENSE_RANK() OVER(ORDER BY n.n DESC) rang,b.citation FROM n JOIN bibliography b USING(reference_id) ORDER BY n.n DESC LIMIT 10",'Concentration de documentation, sans inférence d’abondance biologique.'),
('10','Quelle précision de localisation est déclarée ?',"SELECT coordinate_basis,coordinate_precision,COUNT(*) collections FROM fossil_site GROUP BY coordinate_basis,coordinate_precision ORDER BY collections DESC",'Précision d’écriture ne garantit pas l’exactitude de terrain ; les valeurs inconnues sont conservées.'),
('11','Des parcelles recoupent-elles plusieurs zones ?',"SELECT p.parcel_id,p.commune_code,COUNT(DISTINCT pz.zone_id) zones,GROUP_CONCAT(DISTINCT uz.zone_type) types FROM parcel p LEFT JOIN parcel_zone pz USING(parcel_id) LEFT JOIN urban_zone uz USING(zone_id) GROUP BY p.parcel_id HAVING COUNT(DISTINCT pz.zone_id)>1 ORDER BY zones DESC",'Échantillon de parcelles seulement ; ni droit à construire ni exhaustivité nationale.'),
('12','Quels documents ont des dates manquantes ?',"SELECT type,COUNT(*) documents,SUM(approval_date IS NULL OR approval_date='') approbation_absente,SUM(publication_date IS NULL OR publication_date='') publication_absente FROM urban_document GROUP BY type",'Un champ absent impose une vérification dans le document officiel.'),
('13','Intersection avec les seules enveloppes livrées ?',"SELECT t.label,h.hazard_id,COUNT(*) zones_testees,SUM(ST_IntersectsPoint(h.geometry,t.longitude,t.latitude)) intersections FROM test_place t CROSS JOIN hazard_zone h GROUP BY t.place_id,h.hazard_id ORDER BY t.label,h.hazard_id",'Test point/polygone GEOS : hors enveloppe livrée ne signifie pas sans risque. Pas une surface de population exposée.'),
('14','Effet du seuil personnel de chaleur sur une comparaison ?',"WITH thresholds(n) AS (VALUES(5),(10),(20),(30)), places AS (SELECT * FROM commune WHERE code IN('17300','13004','31555','2A004','97411')) SELECT t.n threshold,c.name,cp.domain,v.value,CASE WHEN v.value IS NULL THEN 'non documenté' WHEN v.value>t.n THEN 'seuil dépassé' ELSE 'dans le seuil choisi' END resultat FROM thresholds t CROSS JOIN places c LEFT JOIN climate_place cp ON cp.commune_code=c.code LEFT JOIN climate_value v ON v.commune_code=c.code AND v.indicator_id='S1' AND v.period_id='2050' AND v.season='annuel' ORDER BY t.n,c.name",'Sensibilité d’une contrainte utilisateur ; aucune pondération ni score d’habitabilité. Comparer les domaines distincts avec précaution.'),
('15','À quelle distance géodésique sont les collections proches de La Rochelle ?',"SELECT s.site_id,s.name,ROUND(ST_DistanceMeters(s.longitude,s.latitude,c.longitude,c.latitude)/1000,2) km,s.coordinate_precision FROM fossil_site s CROSS JOIN commune c WHERE c.code='17300' AND s.site_id IN(SELECT site_id FROM fossil_index WHERE min_lon BETWEEN -3 AND 0 AND min_lat BETWEEN 45 AND 47) ORDER BY km LIMIT 15",'Distance ellipsoïdale WGS84, pas distance en degrés ni précision de la découverte.'),
]
def main():
 db=sqlite3.connect(ROOT/'data/curated/france.sqlite');db.row_factory=sqlite3.Row;geod=Geod(ellps='WGS84')
 db.create_function('ST_IntersectsPoint',3,lambda g,x,y:int(shape(json.loads(g)).intersects(Point(x,y))))
 db.create_function('ST_DistanceMeters',4,lambda x,y,a,b:geod.inv(x,y,a,b)[2])
 sql=['-- SQLite + fonctions spatiales Python/GEOS et PROJ enregistrées par python -m national.analyze.\n'];out=[]
 for id,question,q,note in ANALYSES:
  t=time.perf_counter();rows=[dict(r) for r in db.execute(q)];out.append({'id':id,'question':question,'sql':q,'rows':rows,'row_count':len(rows),'duration_ms':round(1000*(time.perf_counter()-t),2),'interpretation':note});sql.append('-- '+id+' '+question+'\n-- '+note+'\n'+q+';\n')
 (ROOT/'sql/france_analyses.sql').write_text('\n'.join(sql),encoding='utf8');dump(ROOT/'reports/france_sql_results.json',out)
 lines=['# Quinze analyses exécutées','Commande : `python -m national.analyze`. Base nationale livrée. Les résultats complets sont dans `reports/france_sql_results.json`.']
 for a in out:
  lines+=['\n## '+a['id']+' — '+a['question'],a['interpretation'],str(a['row_count'])+' lignes ; '+str(a['duration_ms'])+' ms.','```json',json.dumps(a['rows'][:5],ensure_ascii=False,indent=2),'```']
 (ROOT/'docs/analyses_france.md').write_text('\n'.join(lines),encoding='utf8');print('15 analyses exécutées')
if __name__=='__main__':main()
